import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")

    system = platform.system()
    if system == "Windows":
        cmd = ["powershell", "-Command", "Get-Counter '\\Processor(_Total)\\% Processor Time' | Select-Object -ExpandProperty CounterSamples | Select-Object -ExpandProperty CookedValue"]
    else:
        cmd = ["top", "-bn1", "-i"]

    data = []
    start_time = time.time()

    while time.time() - start_time < duration:
        try:
            if system == "Windows":
                output = subprocess.check_output(cmd, stderr=subprocess.STDOUT)
                cpu_percent = float(output.decode().strip())
            else:
                output = subprocess.check_output(cmd, stderr=subprocess.STDOUT)
                lines = output.decode().splitlines()
                for line in lines:
                    if "Cpu(s)" in line:
                        parts = line.split()
                        cpu_percent = float(parts[1].replace(',', '.'))
                        break
                else:
                    cpu_percent = 0.0

            record = {
                "timestamp": time.time(),
                "cpu_usage": cpu_percent
            }
            data.append(record)
        except Exception:
            pass

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

