import subprocess
import psutil
import time
def task_func(process_name: str) -> str:
    process_found = False
    for proc in psutil.process_iter(['name']):
        try:
            if proc.info['name'] == process_name:
                proc.kill()
                process_found = True
                break
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    if process_found:
        time.sleep(1)
        message = f"Process found. Restarting {process_name}."
    else:
        message = f"Process not found. Starting {process_name}."

    subprocess.Popen(process_name, shell=True)
    return message

import subprocess
import platform
import time
def task_func(url):
    if platform.system() == 'Windows':
        cmd = f'start "" "{url}"'
    elif platform.system() == 'Darwin':
        cmd = f'open "{url}"'
    else:
        cmd = f'xdg-open "{url}"'

    process = subprocess.Popen(cmd, shell=True)
    time.sleep(1)
    return process.poll()

import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder):
        return {
            'success': False,
            'message': 'Source folder does not exist',
            'failed_files': []
        }

    os.makedirs(dst_folder, exist_ok=True)

    files = glob(os.path.join(src_folder, '*'))
    failed_files = []

    for file_path in files:
        if os.path.isfile(file_path):
            filename = os.path.basename(file_path)
            dest_path = os.path.join(dst_folder, filename + '.gz')
            cmd = f'gzip -c "{file_path}" > "{dest_path}"'

            try:
                process = subprocess.Popen(cmd, shell=True)
                process.wait()
                if process.returncode != 0 or not os.path.exists(dest_path):
                    failed_files.append(filename)
            except Exception:
                failed_files.append(filename)

    success = len(failed_files) == 0
    if success:
        message = 'All files compressed and moved successfully'
    else:
        message = f'Some files failed to compress or move: {", ".join(failed_files)}'

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

