import subprocess
# Constants
PYTHON_VERSION = '3.8'
PATH_TO_APPEND = '/path/to/whatever'
def task_func(python_version=PYTHON_VERSION, path_to_append=PATH_TO_APPEND):
    try:
        subprocess.run(f'pyenv shell {python_version}', shell=True, check=True)
    except subprocess.CalledProcessError:
        pass

    if path_to_append not in sys.path:
        sys.path.append(path_to_append)

    result = subprocess.run(['python', '--version'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
    if result.returncode == 0:
        version_str = result.stdout.decode('utf-8').strip()
    else:
        version_str = f'Python {python_version}'

    return version_str

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.isfile(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    total_cpu = 0.0
    total_memory = 0

    process = subprocess.Popen(['bash', script_path], shell=True)

    try:
        proc = psutil.Process(process.pid)
        start_time = time.time()

        while True:
            if time.time() - start_time > timeout:
                proc.terminate()
                break

            if proc.status() == psutil.STATUS_ZOMBIE:
                break

            try:
                cpu = proc.cpu_percent(interval=0)
                mem = proc.memory_info().rss
                total_cpu += cpu
                total_memory += mem
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                break

            if process.poll() is not None:
                break

            time.sleep(0.1)

    except psutil.NoSuchProcess:
        pass

    return {'CPU Usage': total_cpu, 'Memory Usage': total_memory}
